import type { EditorPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import { getTextButtons } from './get-text-buttons.js';
import { lineSpacing } from './tiptap.js';
import type { LineSpacingPluginEditorConfig } from './types.js';
import { LINE_SPACING_TYPE } from './types.js';

export const pluginLineSpacing: EditorPluginCreator<LineSpacingPluginEditorConfig> = config => {
  const resolvedConfig = { type: 'lineSpacing' as const, ...DEFAULTS.config, ...config };
  return {
    config: resolvedConfig,
    type: LINE_SPACING_TYPE,
    textButtons: getTextButtons(resolvedConfig),
    tiptapExtensions: [lineSpacing],
  };
};
