import React from 'react';

import type { ThemeData, ThemeStrategyArgs, ThemeStrategyResult } from './../../ricos-types/index.js';

import { createCustomStyles } from './generators/custom-styles.js';
import { createPalette } from './generators/palette.js';
import { createTypography } from './generators/typography.js';
import * as utils from './theme-utils.js';

// TODO: remove in v11
// @deprecated
export function themeStrategy(args: ThemeStrategyArgs): ThemeStrategyResult {
  const { buildCssVars } = utils;
  const { ricosTheme = {} } = args;
  const {
    parentClass = '',
    palette,
    paletteConfig,
    typography,
    customStyles,
    settingsStyles,
    nativeStyle,
  } = ricosTheme;

  // Create CSS Vars
  const { paletteVarsObject, colors } = createPalette(palette, paletteConfig);
  const typographyVarsObject = createTypography(typography);
  const customsVarsObject = createCustomStyles({
    customStyles,
    settingsStyles,
    nativeStyle,
  });

  const themeData: ThemeData = {
    colors,
    utils,
    customStyles,
  };

  const html = (
    <style type="text/css" key={'styleElement'}>
      {buildCssVars(parentClass, paletteVarsObject, typographyVarsObject, customsVarsObject)}
    </style>
  );

  return {
    html,
    themeData,
  };
}
