import type { Decoration, SketchData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { CustomTextualStyle } from './../../ricos-types/index.js';

import type { TextDecoration } from '../models/decoration.js';
import { EmptyDecoration } from './empty-decoration.js';

export class SketchDecoration implements TextDecoration {
  type = Decoration_Type.SKETCH;

  private readonly data: SketchData | undefined;

  private constructor(data: SketchData | undefined) {
    this.data = data;
  }

  static of(decoration: Decoration) {
    if (decoration.type !== Decoration_Type.SKETCH) {
      throw new TypeError(`invalid decoration initializer ${decoration}`);
    }
    return new SketchDecoration(decoration.sketchData);
  }

  getDecoration(): Decoration {
    return {
      type: this.type,
      ...(this.data && { sketchData: this.data }),
    };
  }

  fromCustomStyle(_customStyle: CustomTextualStyle): TextDecoration {
    return new SketchDecoration(this.data);
  }

  toCustomStyle(): CustomTextualStyle {
    return {};
  }

  overrideWith(decoration: TextDecoration): TextDecoration {
    if (!(decoration instanceof SketchDecoration || decoration instanceof EmptyDecoration)) {
      throw new TypeError(`invalid merge decoration ${decoration}`);
    }
    if (decoration instanceof EmptyDecoration) {
      return this;
    }
    return new SketchDecoration(decoration.data);
  }
}
