import React, { Suspense, lazy } from 'react';

import type { InsertDecorationModalProps } from './insert-decoration-modal/insert-decoration-modal.js';

const InsertDecorationModal = lazy(() =>
  import('./insert-decoration-modal/insert-decoration-modal.js').then(
    ({ InsertDecorationModal }) => ({
      default: InsertDecorationModal,
    })
  )
);

export const LineSpacingPanelComponent = (props: InsertDecorationModalProps) => (
  <Suspense fallback={<div style={{ width: 143 }} />}>
    <InsertDecorationModal {...props} />
  </Suspense>
);
