import type { ReactElement } from 'react';

import type {
  Decoration,
  Node,
  DocumentStyle as RichContentDocumentStyle,
  TextNodeStyle,
} from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type, Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { getDocumentStyleKey, toDocumentStyle } from './../text-node-transformer.js';
import type { HeadingNode, ParagraphNode } from './../../ricos-types/index.js';

import { Decorations } from '../decorations/index.js';
import type { TextDecoration } from '../models/decoration.js';
import type { TextBlockNodeType } from '../models/styles.js';
import { TextStyleTransformer } from '../text-style-transformer.js';
import { RicosTextualTheme } from '../textual-theme/textual-theme.js';
import { RicosNodeStyle } from './node-style.js';
import { RicosTextNodeStyle } from './text-node-style.js';
import { RicosTextStyle } from './text-style.js';

/**
 * Represents Document Style
 */
export class RicosDocumentStyle {
  documentStyle: RichContentDocumentStyle;

  constructor(documentStyle: RichContentDocumentStyle) {
    this.documentStyle = removeUnsupportedDocumentStyleDecorations(documentStyle);
  }

  static fromNode(node: ParagraphNode | HeadingNode): RicosDocumentStyle {
    return new RicosDocumentStyle(toDocumentStyle(node));
  }

  static isNodeTransformable(node: Node): node is ParagraphNode | HeadingNode {
    return node.type === Node_Type.PARAGRAPH || node.type === Node_Type.HEADING;
  }

  /**
   * Extracts given decoration settings for specific node type from the current Document Style.
   */
  getDecoration(nodeType: TextBlockNodeType, decorationType: Decoration_Type): TextDecoration {
    return Decorations.of(this.documentStyle[nodeType]?.decorations || []).byType(decorationType);
  }

  getDecorations(node: ParagraphNode | HeadingNode): Decoration[] {
    const documentStyleKey = getDocumentStyleKey(node);
    return Decorations.of(
      this.documentStyle[documentStyleKey]?.decorations || []
    ).toDecorationArray();
  }

  getTextStyle(nodeType: TextBlockNodeType) {
    return RicosTextStyle.of({ lineHeight: this.documentStyle[nodeType]?.lineHeight });
  }

  getNodeStyle(nodeType: TextBlockNodeType) {
    return RicosNodeStyle.of(this.documentStyle[nodeType]?.nodeStyle);
  }

  /**
   * Translates DocumentStyle to HTML style tag with CSS variable definitions
   */
  toStyleTag(): ReactElement {
    const theme = TextStyleTransformer.fromDocumentStyle(this.documentStyle).toTheme();
    return new RicosTextualTheme(theme).toStyleTag();
  }

  /**
   * Translates DocumentStyle entity to RichContent compatible DocumentStyle object
   */
  toContent(): RichContentDocumentStyle {
    return this.documentStyle;
  }

  /**
   * DocumentStyle modification
   */
  setStyle(nodeType: TextBlockNodeType, textNodeStyle: TextNodeStyle): RicosDocumentStyle {
    const style = new RicosTextNodeStyle(this.documentStyle[nodeType] || { decorations: [] })
      .overrideWith(textNodeStyle)
      .getTextNodeStyle();
    return new RicosDocumentStyle({ ...this.documentStyle, [nodeType]: style });
  }

  resetStyle(nodeType: TextBlockNodeType): RicosDocumentStyle {
    return new RicosDocumentStyle({ ...this.documentStyle, [nodeType]: {} });
  }

  /**
   * DocumentStyle modification
   */
  mergeWith(documentStyle: RichContentDocumentStyle): RicosDocumentStyle {
    return (
      Object.entries(documentStyle) as [keyof RichContentDocumentStyle, TextNodeStyle][]
    ).reduce(
      (acc, [key, style]) => acc.setStyle(key, style),
      new RicosDocumentStyle(this.documentStyle)
    );
  }
}

const unsupportedDocumentStyleDecorations = [Decoration_Type.SKETCH];

const removeUnsupportedDocumentStyleDecorations = (
  documentStyle: RichContentDocumentStyle
): RichContentDocumentStyle =>
  (
    Object.entries(documentStyle || {}) as [keyof RichContentDocumentStyle, TextNodeStyle][]
  ).reduce<RichContentDocumentStyle>((acc, [key, style]) => {
    if (!style.decorations) {
      acc[key] = style;
      return acc;
    }
    acc[key] = {
      ...style,
      decorations: style.decorations.filter(
        decoration => !unsupportedDocumentStyleDecorations.includes(decoration.type)
      ),
    };
    return acc;
  }, {});
