import { Node_Type, type RicosExtension, type RicosExtensionConfig } from './../ricos-types/index.js';
import { normalizeLineHeight } from './../_shared/line-spacing-utils.js';
import { createRicosFunctionalExtension } from './../plugin-commons/index.js';

import type { LineSpacings } from './types.js';

declare module './../tiptap/core' {
  interface Commands<ReturnType> {
    lineSpacing: {
      /**
       * Set the text line spacings
       */
      setLineSpacings: (lineSpacings: LineSpacings) => ReturnType;
      /**
       * Set the text line spacing
       */
      setLineSpacing: (lineSpacing: number) => ReturnType;
      /**
       * Set the text line spacing before
       */
      // maybe it should have a style extension?
      setLineSpacingBefore: (lineSpacing: number) => ReturnType;
      /**
       * Set the text line spacing after
       */
      setLineSpacingAfter: (lineSpacing: number) => ReturnType;
    };
  }
}

export const lineSpacing = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'lineSpacing',
  reconfigure(config: RicosExtensionConfig, _extensions: RicosExtension[]) {
    const types = [
      Node_Type.PARAGRAPH,
      Node_Type.HEADING,
      Node_Type.CODE_BLOCK,
      Node_Type.BLOCKQUOTE,
      Node_Type.CAPTION,
    ];
    return {
      ...config,
      addGlobalAttributes() {
        return [
          {
            types,
            attributes: {
              textStyle: {
                renderHTML: attributes => {
                  const styles: string[] = [];
                  if (!isNaN(attributes?.textStyle?.lineHeight)) {
                    styles.push(
                      `line-height:${normalizeLineHeight(attributes.textStyle.lineHeight)}`
                    );
                  }
                  return {
                    style: styles.join(';'),
                  };
                },
              },
            },
          },
          {
            types,
            attributes: {
              style: {
                renderHTML: attributes => {
                  const styles: string[] = [];

                  if (attributes?.style?.paddingTop) {
                    styles.push(`padding-top:${attributes.style.paddingTop}`);
                  }
                  if (attributes?.style?.paddingBottom) {
                    styles.push(`padding-bottom:${attributes.style.paddingBottom}`);
                  }
                  return {
                    style: styles.join(';'),
                  };
                },
              },
            },
          },
        ];
      },
      addCommands() {
        return {
          setLineSpacings:
            lineSpacings =>
            ({ chain }) => {
              const {
                'line-height': stringLineHeight,
                'padding-bottom': stringPaddingBottom,
                'padding-top': stringPaddingTop,
              } = lineSpacings;
              const lineHeight = parseFloat(stringLineHeight);
              const paddingBottom = parseFloat(stringPaddingBottom);
              const paddingTop = parseFloat(stringPaddingTop);

              return chain()
                .focus()
                .setLineSpacing(lineHeight)
                .setLineSpacingBefore(paddingTop)
                .setLineSpacingAfter(paddingBottom)
                .run();
            },
          setLineSpacing:
            (lineSpacing: number) =>
            ({ commands }) => {
              if (lineSpacing > 100 || lineSpacing < 0) {
                return false;
              }
              return types
                .map(type =>
                  commands.updateAttributesWithDeepMerge(type, {
                    textStyle: { lineHeight: lineSpacing },
                  })
                )
                .every(Boolean);
            },
          setLineSpacingBefore:
            (lineSpacing: number) =>
            ({ commands }) => {
              if (lineSpacing > 250 || lineSpacing < 0) {
                return false;
              }
              return types
                .map(type =>
                  commands.updateAttributesWithDeepMerge(type, {
                    style: {
                      paddingTop: `${lineSpacing}px`,
                    },
                  })
                )
                .every(Boolean);
            },
          setLineSpacingAfter:
            (lineSpacing: number) =>
            ({ commands }) => {
              if (lineSpacing > 250 || lineSpacing < 0) {
                return false;
              }
              return types
                .map(type =>
                  commands.updateAttributesWithDeepMerge(type, {
                    style: {
                      paddingBottom: `${lineSpacing}px`,
                    },
                  })
                )
                .every(Boolean);
            },
        };
      },
    };
  },
  createExtensionConfig() {
    return {
      name: this.name,
    };
  },
});
