import type {
  CssVarsObject,
  RicosCustomStyles,
  RicosNativeStyles,
  RicosSettingsStyles,
} from './../../../ricos-types/index.js';
import { deepMerge } from './../../../_shared/deep-merge.js';
import { resolveDocumentColorToCss } from './../../../_shared/theme-color-token.js';

type NestedObject = {
  [key: string]: any;
};

/**
 * Sets `lineHeight` to `1.5` when `fontSize` is provided without `lineHeight`.
 * @param param0 CustomTextualStyle element
 */
export function fixLineHeight(obj: NestedObject): NestedObject {
  return {
    ...Object.fromEntries(
      Object.entries(obj).map(([key, value]) => [
        key,
        typeof value === 'object' && value !== null ? fixLineHeight(value) : value,
      ])
    ),
    ...(obj.fontSize !== undefined && obj.lineHeight === undefined ? { lineHeight: 1.5 } : {}),
  };
}

function toVars(
  customStyles: RicosCustomStyles | RicosSettingsStyles | RicosNativeStyles,
  prefix = '',
  separator = '-'
): { [propertyName: string]: string } {
  const propertyNames: { [key: string]: string } = {};

  function traverseObject(currentObj: NestedObject, currentPath = '') {
    for (const [key, value] of Object.entries(currentObj)) {
      const fullPath = currentPath ? `${currentPath}${separator}${key}` : key;
      if (typeof value === 'object') {
        traverseObject(value, fullPath);
      } else {
        const resolved =
          typeof value === 'string' ? (resolveDocumentColorToCss(value) ?? value) : value;
        propertyNames[`${prefix ? prefix + '-' : ''}${fullPath}`] = resolved;
      }
    }
  }
  traverseObject(customStyles);

  return propertyNames;
}

type CreateCustomStyles = (param: {
  customStyles?: RicosCustomStyles;
  settingsStyles?: RicosSettingsStyles;
  nativeStyle?: RicosNativeStyles;
}) => CssVarsObject;

export const createCustomStyles: CreateCustomStyles = ({
  customStyles = {},
  settingsStyles = {},
  nativeStyle = {},
}) => {
  return deepMerge(
    {},
    toVars(fixLineHeight(customStyles), 'custom'),
    toVars(settingsStyles, 'settings'),
    toVars(nativeStyle, 'native')
  );
};
