import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem } from './../../../../ricos-types/toolbar-types.js';
import { DropdownButton } from './../../../../_shared/dropdown-button.js';
import {
  LINE_SPACING_CUSTOM_SPACING_MODAL_ID,
  LINE_SPACING_MODAL_ID,
} from './../../../../plugin-line-spacing/consts.js';

export const LineSpacingButton = ({
  toolbarItem,
  dataHook,
}: {
  toolbarItem: IToolbarItem;
  dataHook?: string;
}) => {
  const { t } = useContext(RicosContext);
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const Icon = toolbarItem.presentation?.icon;
  const tooltip = t(toolbarItem.presentation?.tooltip);
  const isLineSpacingModalOpen = useModalState(getIsModalOpen(LINE_SPACING_MODAL_ID));
  const isCustomLineSpacingModalOpen = useModalState(
    getIsModalOpen(LINE_SPACING_CUSTOM_SPACING_MODAL_ID)
  );

  return (
    <DropdownButton
      ref={setReferenceElement}
      disabled={toolbarItem.attributes.disabled}
      active={isLineSpacingModalOpen || isCustomLineSpacingModalOpen}
      tooltip={tooltip}
      onClick={() => {
        toolbarItem.commands?.click({ referenceElement });
      }}
      icon={Icon}
      dataHook={dataHook}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
