import type { DocumentStyle } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { RichTextNode } from './../ricos-types/index.js';

import { Decorations } from './decorations/index.js';

type DocumentStyleKey = keyof DocumentStyle;

const nodeTypeToDocumentKeyMap: Record<string, DocumentStyleKey> = {
  [(Node_Type.HEADING, 1)]: 'headerOne',
  [(Node_Type.HEADING, 2)]: 'headerTwo',
  [(Node_Type.HEADING, 3)]: 'headerThree',
  [(Node_Type.HEADING, 4)]: 'headerFour',
  [(Node_Type.HEADING, 5)]: 'headerFive',
  [(Node_Type.HEADING, 6)]: 'headerSix',
  [Node_Type.PARAGRAPH]: 'paragraph',
  [Node_Type.BLOCKQUOTE]: 'blockquote',
  [Node_Type.CODE_BLOCK]: 'codeBlock',
};

const nodeTypeToNodeDataKey: Record<string, string> = {
  [Node_Type.HEADING]: 'headingData',
  [Node_Type.PARAGRAPH]: 'paragraphData',
  [Node_Type.BLOCKQUOTE]: 'blockquoteData',
  [Node_Type.CODE_BLOCK]: 'codeBlockData',
};

const getTextNodes = (node: RichTextNode) =>
  node.type === Node_Type.BLOCKQUOTE ? node.nodes[0].nodes : node.nodes;

export const toDocumentStyle = (node: RichTextNode): DocumentStyle => {
  const type = getDocumentStyleKey(node);
  return {
    [type]: {
      decorations: getTextNodes(node)
        .reduce(
          (acc, node) => acc.overrideWith(node.textData.decorations ?? []),
          Decorations.of([])
        )
        .toDecorationArray(),
      nodeStyle: node.style,
      // @ts-expect-error
      lineHeight: (node[nodeTypeToNodeDataKey[node.type]].textStyle || {}).lineHeight,
    },
  };
};

export const getDocumentStyleKey = (node: RichTextNode) => {
  const level = node.type === Node_Type.HEADING ? node.headingData.level : undefined;
  return nodeTypeToDocumentKeyMap[level ? (node.type, level) : node.type];
};
